import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# DEUTERONOMY 1-3, THE READING: THE SECOND MEASUREMENT PASS — every candidate ink fact PRINTED from the Tanakh DB and the shelf's bytes, so
# that deu_ink.py's asserts are typed FROM THE PRINT. The retellings diffed token by token against their first tellings. Nothing asserted.
import json, os, re, html, sqlite3, subprocess, unicodedata
from collections import Counter
ROOT = _ROOT
def clean(s): return re.sub(r'<[^>]+>', '', html.unescape(s))
def plain(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
def pointed(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05AF))
def NF(s): return unicodedata.normalize('NFC', s)
db = sqlite3.connect(f'file:{ROOT}/Data/tanakh.sqlite?mode=ro', uri=True)
rows = db.execute("SELECT v.book, v.chapter, v.verse, w.he, w.morph, w.lemma FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.id, w.idx").fetchall()
by = {}
for b, c, v, he, m, lem in rows: by.setdefault((b, c, v), []).append((plain(he), m, he, lem))
T = ('Gen', 'Exod', 'Lev', 'Num', 'Deut')
def words(b, c, v): return [x for x, _, _, _ in by[(b, c, v)]]
def wm(b, c, v): return [(x, m) for x, m, _, _ in by[(b, c, v)]]
def raw(b, c, v): return [(x, m, NF(pointed(r))) for x, m, r, _ in by[(b, c, v)]]
def base(l): return (l or '').split('/')[-1].strip()
def hits(sub, books=None, exact=True): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) and any((x == sub) if exact else (sub in x) for x, _, _, _ in ws)})
def U(*toks, books=None): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if books is None or b in books for x, _, _, _ in ws if x in toks})
def phrase(seq, books=None):
    out = []
    for (b, c, v), ws in by.items():
        if books is not None and b not in books: continue
        w = [x for x, _, _, _ in ws]
        if any(w[i:i + len(seq)] == list(seq) for i in range(len(w) - len(seq) + 1)): out.append(f'{b} {c}:{v}')
    return sorted(out)
def P(*seq, books=None): return phrase(list(seq), books)
def LEMT(lem, books=None): return [(f'{b} {c}:{v}', x, m) for (b, c, v), ws in by.items() if (books is None or b in books) for x, m, _, l in ws if base(l) == lem]
def LEMV(lem, books=None): return sorted({s for s, _, _ in LEMT(lem, books)})
def lemma_of(b, c, v, tok): return [base(l) for x, _, _, l in by[(b, c, v)] if x == tok]
def FAM(sub, books=None): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) for x, _, _, _ in ws if sub in x})
def DIFF(a, b_):
    A, B = words(*a), words(*b_)
    import difflib
    sm = difflib.SequenceMatcher(a=A, b=B)
    out = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'equal': out.append('=' + ' '.join(A[i1:i2]))
        else: out.append(f'[{tag}: {" ".join(A[i1:i2])!r} -> {" ".join(B[j1:j2])!r}]')
    return f'{a[0]} {a[1]}:{a[2]} ({len(A)}) vs {b_[0]} {b_[1]}:{b_[2]} ({len(B)}): ' + ' '.join(out)
onk = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Deuteronomy/en.json', encoding='utf-8'))['text']
onk_he = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Deuteronomy/he.json', encoding='utf-8'))['text']
onkN_he = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/he.json', encoding='utf-8'))['text']
def arm(c, v): return [plain(x) for x in clean(onk_he[c - 1][v - 1]).rstrip(':').split()]
def armN(c, v): return [plain(x) for x in clean(onkN_he[c - 1][v - 1]).rstrip(':').split()]
def onk_seats(sub): return [(c + 1, v + 1) for c in range(34) for v in range(len(onk_he[c])) if sub in ' '.join(arm(c + 1, v + 1))]
def onk_tok(tok): return [(c + 1, v + 1) for c in range(34) for v in range(len(onk_he[c])) if tok in arm(c + 1, v + 1)]
he = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Devarim/he.json', encoding='utf-8'))['text']
en = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Devarim/en.json', encoding='utf-8'))['text']
def Hb(p, r): return clean(he[p - 1][r - 1])
def E(p, r): return clean(en[p - 1][r - 1])

print('==== A. THE SHELF: the outside rows (HE form) whole, the ibid scan, the EN "Dt." scan')
for p, r in ((37, 9), (37, 11), (52, 1), (54, 2), (82, 5), (199, 5), (314, 2)):
    h = Hb(p, r); m = re.search(r'\(דברים [אבג] [א-ת]+\)', h)
    print(f'  {p}:{r} head {re.search(r"^\(([^)]+)\)", Hb(p, 1)).group(1) if re.search(r"^\(([^)]+)\)", Hb(p, 1)) else "?"} | cite {m.group(0) if m else None} | HE {h[max(0, (m.start() if m else 0) - 150):(m.end() if m else 0) + 120]!r}')
    print(f'      EN head {E(p, r)[:100]!r}')
HEB = {'א': 1, 'ב': 2, 'ג': 3, 'ד': 4, 'ה': 5, 'ו': 6, 'ז': 7, 'ח': 8, 'ט': 9, 'י': 10, 'כ': 20, 'ל': 30, 'מ': 40, 'נ': 50, 'ס': 60, 'ע': 70, 'פ': 80, 'צ': 90, 'ק': 100}
def gem(s): return sum(HEB.get(ch, 0) for ch in s)
IB = []
for p in range(31, 358):
    for r, row in enumerate(he[p - 1], 1):
        t = clean(row)
        for mm in re.finditer(r'\((שם) ([א-ת]{1,3}) ([א-ת]{1,3})\)', t):
            prior = re.findall(r'\(([א-ת]+(?: [א-ת])?) [א-ת]{1,3} [א-ת]{1,3}\)', t[:mm.start()])
            prior = [x for x in prior if x != 'שם']
            book = prior[-1] if prior else None
            if book == 'דברים' and gem(mm.group(2)) in (1, 2, 3): IB.append((p, r, gem(mm.group(2)), gem(mm.group(3))))
print('  HE ibid rows (שם) resolving to Deuteronomy 1-3 outside 1-30:', IB)
ENC = [(p, r, m.group(0)) for p in range(31, 358) for r, row in enumerate(en[p - 1], 1) for m in re.finditer(r'\((?:Dt|Deut|Deuteronomy|Devarim)\.?\s?([123]):(\d+)', clean(row))]
print('  EN rows citing Dt. 1-3 outside 1-30:', len(ENC), ENC[:40])
print('  the piskaot 1-30 rows: 1-25 rows', sum(len(he[p - 1]) for p in range(1, 26)), '| 26-30 rows', sum(len(he[p - 1]) for p in range(26, 31)))
print('  piska 14 HE opens (no paren):', Hb(14, 1)[:80], '| piska 27 HE opens:', Hb(27, 1)[:80])
print('  citation books in the HE rows of 1-30 (Counter):', Counter(b for p in range(1, 31) for row in he[p - 1] for b in re.findall(r'\(([א-ת]+(?: [א-ת])?) [א-ת]{1,3} [א-ת]{1,3}(?:-[א-ת]{1,3})?\)', clean(row))).most_common(30))
print('  EN footnote markers per row in piska 1 (the EN carries H:/JN: apparatus):', [len(re.findall(r'\d+[A-Z][a-z]', E(1, r))) for r in range(1, 21)])

