print('  אלה הדברים:', P('אלה', 'הדברים'), '| אשר דבר משה:', P('אשר', 'דבר', 'משה'), '| אל כל ישראל:', P('אל', 'כל', 'ישראל', books=T), '| בעבר הירדן Torah:', P('בעבר', 'הירדן', books=T), '| Bible count:', len(P('בעבר', 'הירדן')))
